import{_ as t,o as a,c as d,a3 as i}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Leads inactivity manager digest (1.9.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leads inactivity manager digest (1.9.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/leads-inactivity-digest-1-9-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leads inactivity manager digest (1.9.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/leads-inactivity-digest-1-9-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/leads-inactivity-digest-1-9-0-production-readiness.md","filePath":"deployment/leads-inactivity-digest-1-9-0-production-readiness.md","lastUpdated":1791634769000}'),o={name:"deployment/leads-inactivity-digest-1-9-0-production-readiness.md"};function n(s,e,r,l,c,g){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="leads-inactivity-manager-digest-1-9-0-—-production-readiness-audit" tabindex="-1">Leads inactivity manager digest (1.9.0) — Production Readiness Audit <a class="header-anchor" href="#leads-inactivity-manager-digest-1-9-0-—-production-readiness-audit" aria-label="Permalink to &quot;Leads inactivity manager digest (1.9.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-05</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (migrate catalog + deploy SPA + restart <code>emails</code> queue)</td></tr><tr><td><strong>Scope</strong></td><td>Replace per-lead inactivity bursts with one assignee digest and one manager table email; keep assignment; Settings → Leads knobs; catalog <strong>leads 1.8.0 → 1.9.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/leads">Leads developer guide</a> · <a href="/user-guide/tenant-settings">Tenant settings</a> · <a href="/deployment/upgrade">Upgrade</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Idle assigned leads no longer fire one in-app/push notification per record. The existing daily <code>leads:notify-inactive</code> job groups idle leads per assignee and per manager (department manager, else workspace owner). Assignees get one bell/push digest. Managers get the same plus one branded HTML email with clickable lead name, phone, and email. <strong>Leads stay assigned.</strong> Won/Lost stages remain excluded. New workspace settings control Active-only, skip future follow-ups, manager email, assignee notify, and reminder cadence.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (existing settings + notification stack; no parallel shell)</td><td><strong>Pass</strong></td></tr><tr><td>Assignment unchanged</td><td><strong>Pass</strong> — command never writes <code>assigned_to</code></td></tr><tr><td>Won/Lost still skipped</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Active-only skips Closed</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Future pending follow-up skipped</td><td><strong>Pass</strong> — Pest (<code>UtcInstant</code> vs <code>due_at</code>)</td></tr><tr><td>One digest per recipient (not per lead)</td><td><strong>Pass</strong> — Pest two-lead case</td></tr><tr><td>Manager mail gated by <code>leads.inactivity_manager_email</code></td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Threshold <code>0</code> disables job</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Reminder period dedupe (default 7 working days)</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Settings GET/PUT for new keys</td><td><strong>Pass</strong> — Pest</td></tr><tr><td>Catalog migrate-only <strong>1.9.0</strong> + CatalogSeeder companion</td><td><strong>Pass</strong></td></tr><tr><td>Queued manager mail CTA baked while tenancy is initialized</td><td><strong>Pass</strong> — <code>listUrl</code> + per-lead URLs built in the command</td></tr></tbody></table><h2 id="findings-and-remediations" tabindex="-1">Findings and remediations <a class="header-anchor" href="#findings-and-remediations" aria-label="Permalink to &quot;Findings and remediations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>L-01</td><td>High</td><td>Per-lead alerts on a backlog (100s of push/in-app)</td><td>Digests per recipient; default reminder period 7 working days</td></tr><tr><td>L-02</td><td>High</td><td>First-crossing modulo would skip already-idle backlog</td><td>Include all <code>idleDays &gt;= threshold</code> when reminder &gt; 0; period key on recipient dedupe</td></tr><tr><td>L-03</td><td>Medium</td><td>Queued <code>toMail()</code> calling <code>FrontendUrl::spa</code> after <code>tenancy()-&gt;end()</code></td><td>Bake <code>listUrl</code> and row URLs in the command while tenancy is live</td></tr><tr><td>L-04</td><td>Low</td><td>Optional <code>email_notifications</code> defaults off would hide manager mail</td><td>Gated by <code>leads.inactivity_manager_email</code> (default <strong>on</strong>)</td></tr><tr><td>L-05</td><td>Info</td><td>Legacy <code>LeadInactiveNotification</code> / <code>LeadInactiveOwnerNotification</code> unused by the job</td><td>Kept for already-queued jobs and historical database rows</td></tr></tbody></table><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Settings: <code>leads.inactivity_active_only</code>, <code>leads.inactivity_skip_pending_follow_up</code>, <code>leads.inactivity_manager_email</code>, <code>leads.inactivity_assignee_notify</code>, <code>leads.inactivity_reminder_working_days</code></li><li><code>LeadInactivityService</code> eligibility + digest rows + period dedupe keys</li><li><code>NotifyInactiveLeadsCommand</code> grouped sends</li><li><code>LeadInactiveDigestNotification</code> (<code>lead.inactive.digest</code>)</li><li><code>LeadInactiveManagerDigestNotification</code> (<code>lead.inactive_escalation.digest</code> + branded table mail)</li><li>Catalog migration <code>2026_10_04_193718_bump_leads_module_to_1_9_0</code></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Settings → Leads controls (underscore RHF keys)</li><li>Notification registry for digest types (list href <code>/leads</code>)</li><li>Playwright: <code>e2e/tests/settings/tenant-settings.leads-inactivity.spec.ts</code> (one demo login session)</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User/developer tenant-settings, Leads guides, upgrade, roadmap, changelog, this audit</li></ul><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Tenant/Notification/LeadInactiveNotificationTest.php</span></span>
<span class="line"><span>Tests: 12 passed (37 assertions)</span></span></code></pre></div><p><code>vendor/bin/pint --dirty --format agent</code> — pass.</p><p>Playwright <code>npm run test:e2e:leads-inactivity</code> (<code>--project=tenant</code>): <strong>1 passed</strong> — one-session validate (91 / −1), save 5 / 14 + Active-only off, reload persists, restore 3 / 7 + Active-only on.</p><h2 id="known-limitations-deferred" tabindex="-1">Known limitations / deferred <a class="header-anchor" href="#known-limitations-deferred" aria-label="Permalink to &quot;Known limitations / deferred&quot;">​</a></h2><ul><li>Manager table cap is 25 rows plus “and X more”; full set is still in the in-app digest count.</li><li>Reminder <code>0</code> only includes leads on the exact threshold-crossing working day (missed scheduler day is not backfilled).</li><li>No live SMTP assertion in CI (<code>Notification::fake()</code>). Staging should confirm one manager HTML mail after <code>leads:notify-inactive</code>.</li><li>Historical in-app rows of type <code>lead.inactive</code> remain in the registry for old notifications.</li></ul><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — catalog <code>leads</code> → <strong>1.9.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li><code>php artisan queue:restart</code>.</li><li>Settings → Leads: set invalid 91 days → client validation; save 5 / 14 → reload persists; restore 3 / 7.</li><li>Create two Active assigned leads older than the threshold, run <code>php artisan leads:notify-inactive</code>. Assignee: <strong>one</strong> digest. Manager: <strong>one</strong> email with two clickable rows. Confirm <code>assigned_to</code> unchanged.</li><li>Move a lead to Won: it must not appear in the next digest.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back the catalog migration (<code>down()</code> → <strong>1.8.0</strong>) after rolling back application code. Settings rows are additive; unused keys are harmless. Restore the previous command/notification classes to return to per-lead alerts.</p>`,26)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
